package openai

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"regexp"
	"sort"
	"strings"
	"time"

	"github.com/easel/fizeau/internal/modelmatch"
	"github.com/easel/fizeau/internal/sdk/openaicompat"
)

// ScoredModel is a discovered model with a selection preference score.
// Higher scores are preferred by the auto-selection logic.
type ScoredModel struct {
	// ID is the model identifier returned by the server's /v1/models endpoint.
	ID string
	// CatalogRef is the catalog target ID if this model is recognized in the
	// model catalog for the provider's surface. Empty for unrecognized models.
	CatalogRef string
	// PatternMatch is true when this model matched the configured model_pattern.
	PatternMatch bool
	// Score summarises the selection preference: 3 = catalog-recognized,
	// 2 = pattern-matched, 1 = uncategorized.
	Score int
}

// DiscoverModels queries the generic /v1/models endpoint through the shared
// OpenAI-compatible SDK. It is kept here as a package-level compatibility
// wrapper for existing provider tests and callers inside this package.
func DiscoverModels(ctx context.Context, baseURL, apiKey string) ([]string, error) {
	return openaicompat.DiscoverModels(ctx, baseURL, apiKey)
}

// RankModels scores and sorts a list of discovered model IDs by selection
// preference:
//
//   - Score 3 — catalog-recognized: the model ID appears in knownModels (a map
//     from concrete model ID to catalog target ID, e.g. from
//     Catalog.AllConcreteModels). These are explicitly tracked models; prefer
//     them when auto-selecting.
//   - Score 2 — pattern-matched: the model ID matches the case-insensitive
//     pattern regex (pattern == "" means this tier is skipped).
//   - Score 1 — uncategorized: known to the server but not in the catalog or
//     pattern.
//
// Within each score tier, the original server-returned order is preserved.
// Returns an error only if pattern is non-empty and fails to compile.
func RankModels(candidates []string, knownModels map[string]string, pattern string) ([]ScoredModel, error) {
	var patternRe *regexp.Regexp
	if pattern != "" {
		re, err := regexp.Compile("(?i)" + pattern)
		if err != nil {
			return nil, fmt.Errorf("discovery: invalid model_pattern %q: %w", pattern, err)
		}
		patternRe = re
	}

	scored := make([]ScoredModel, 0, len(candidates))
	for _, id := range candidates {
		sm := ScoredModel{ID: id, Score: 1}
		if ref, ok := knownModels[id]; ok {
			sm.CatalogRef = ref
			sm.Score = 3
		} else if patternRe != nil && patternRe.MatchString(id) {
			sm.PatternMatch = true
			sm.Score = 2
		}
		scored = append(scored, sm)
	}

	// Stable sort: higher score first, original order preserved within tier.
	sort.SliceStable(scored, func(i, j int) bool {
		return scored[i].Score > scored[j].Score
	})
	return scored, nil
}

// SelectModel picks the preferred model ID from a ranked list. Returns ""
// if the list is empty.
func SelectModel(ranked []ScoredModel) string {
	if len(ranked) == 0 {
		return ""
	}
	return ranked[0].ID
}

// getAndDecode performs a GET request with optional Bearer auth and extra
// headers, decodes the JSON response into out, and returns any error.
func getAndDecode(ctx context.Context, timeout time.Duration, endpoint, apiKey string, headers map[string]string, out any) error {
	reqCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	req, err := http.NewRequestWithContext(reqCtx, http.MethodGet, endpoint, nil)
	if err != nil {
		return err
	}
	req.Header.Set("Accept", "application/json")
	if apiKey != "" {
		req.Header.Set("Authorization", "Bearer "+apiKey)
	}
	for k, v := range headers {
		req.Header.Set(k, v)
	}

	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close() //nolint:errcheck

	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 256))
		return fmt.Errorf("HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
	}
	return json.NewDecoder(resp.Body).Decode(out)
}

// MatchModelIDs returns every catalog entry whose normalized form contains
// the normalized request as a substring. Normalization lowercases, strips a
// single leading vendor namespace, and removes all non-alphanumeric
// separators, so "qwen/qwen3.6" and "Qwen3.6" and "qwen3.6" all match
// "Qwen3.6-35B-A3B-4bit" and "Qwen3.6-35B-A3B-nvfp4".
//
// The returned slice preserves original catalog case and order. An empty slice
// means no match; callers are responsible for deciding whether to pass the
// original request through to the provider unchanged or to escalate.
//
// This is the primary matching primitive since v0.9.2 — it replaces the
// scalar logic previously in NormalizeModelID. NormalizeModelID is retained
// as a backward-compatible wrapper.
func MatchModelIDs(requested string, catalog []string) []string {
	return modelmatch.Match(requested, catalog)
}

// NormalizeModelID resolves a caller-supplied model name against the server's
// canonical model catalog (the IDs returned by GET /v1/models).
//
// Prefer MatchModelIDs for new code; this wrapper is retained for backward
// compatibility with the v0.9.1 call signature. Behaviour:
//   - 0 matches → returns the original requested string, no error
//   - 1 match   → returns the catalog entry, no error
//   - 2+ matches → returns "" and an ambiguity error listing the candidates
func NormalizeModelID(requested string, catalog []string) (string, error) {
	if strings.TrimSpace(requested) == "" {
		return requested, nil
	}
	matches := MatchModelIDs(requested, catalog)
	switch len(matches) {
	case 0:
		return requested, nil
	case 1:
		return matches[0], nil
	default:
		return "", fmt.Errorf("ambiguous model %q: matches %v", requested, matches)
	}
}

// Package discoverycache implements the per-source on-disk cache described in
// ADR-012. It provides a two-tier lock + long-lived refresh marker pattern so
// that slow discovery IO (PTY ~30 s, HTTP ~316 ms) never blocks UI reads.
//
// Public surface: Cache.Read, Cache.Refresh, Cache.MaybeRefresh, Cache.Prune.
// The Refresher function is injected; the cache manages single-flight
// deduplication, atomic writes, and crash recovery.
package discoverycache

import (
	"context"
	"errors"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"time"

	"golang.org/x/sync/singleflight"
)

const (
	lockAcquisitionTimeout = 100 * time.Millisecond
	lockPollInterval       = 5 * time.Millisecond
	waitPollInterval       = 250 * time.Millisecond
	stalenessMultiplier    = time.Duration(2)
)

// Cache is the root handle. Root is the base directory (e.g. ~/.cache/fizeau).
// Each Cache instance owns one in-process singleflight.Group; a new Cache per
// process is the normal usage.
type Cache struct {
	Root string
	sf   singleflight.Group
}

// Source describes one cacheable data stream (one file under Root/Tier/Name.json).
type Source struct {
	// Tier is "discovery" or "runtime".
	Tier string
	// Name is the kebab-case source identifier (e.g. "openrouter").
	Name string
	// TTL controls freshness: Read returns Fresh=true when Age < TTL.
	TTL time.Duration
	// RefreshDeadline is the maximum time a refresh is expected to take.
	// Also controls the staleness threshold: 2 × RefreshDeadline.
	RefreshDeadline time.Duration
}

func (s Source) key() string { return s.Tier + "/" + s.Name }

// ReadResult is the output of Cache.Read.
type ReadResult struct {
	// Data is the raw bytes from the cache file; nil if no file exists.
	Data []byte
	// Age is how long ago the data was written (0 if absent).
	Age time.Duration
	// Fresh is true when Age < TTL and Data is non-nil.
	Fresh bool
	// Stale is true when Data is nil or Age >= TTL.
	Stale bool
}

// Refresher is the source-fetch function injected by the caller. The cache
// handles single-flight deduplication, the atomic write, and marker lifecycle.
type Refresher func(ctx context.Context) ([]byte, error)

// Read returns cached data without any IO beyond reading the local file.
// It never blocks on network or PTY. If no cache file exists, Data is nil and
// Stale is true. Stale data is always returned without error; the caller
// decides whether to trigger a background refresh.
func (c *Cache) Read(s Source) (ReadResult, error) {
	path := c.dataPath(s)
	data, err := os.ReadFile(path) // #nosec G304
	if errors.Is(err, os.ErrNotExist) {
		return ReadResult{Stale: true}, nil
	}
	if err != nil {
		return ReadResult{}, err
	}
	info, err := os.Stat(path)
	if err != nil {
		// File was just there; best-effort fallback.
		return ReadResult{Data: data, Stale: true}, nil
	}
	age := time.Since(info.ModTime())
	if age < 0 {
		age = 0
	}
	fresh := age < s.TTL
	return ReadResult{
		Data:  data,
		Age:   age,
		Fresh: fresh,
		Stale: !fresh,
	}, nil
}

// Prune removes data files (and their sidecar lock/marker/tmp files) for
// sources not listed in activeSources. Sources with an active .refreshing
// marker are skipped. Prune acquires the tier-1 lock before removing each
// source's files.
func (c *Cache) Prune(activeSources []Source) error {
	active := make(map[string]bool, len(activeSources))
	for _, s := range activeSources {
		active[s.key()] = true
	}

	return filepath.WalkDir(c.Root, func(path string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return nil
		}
		if !strings.HasSuffix(d.Name(), ".json") {
			return nil
		}
		rel, rerr := filepath.Rel(c.Root, path)
		if rerr != nil {
			return nil
		}
		parts := strings.SplitN(rel, string(filepath.Separator), 2)
		if len(parts) != 2 {
			return nil
		}
		tier := parts[0]
		name := strings.TrimSuffix(parts[1], ".json")
		if strings.ContainsRune(name, filepath.Separator) {
			return nil // nested dir, skip
		}

		if active[tier+"/"+name] {
			return nil
		}

		s := Source{Tier: tier, Name: name}

		// Skip sources with an active refresh in progress.
		m, _ := readMarker(c.markerPath(s))
		if isMarkerActiveForPrune(m) {
			return nil
		}

		release, lerr := c.acquireLock(s)
		if lerr != nil {
			return nil // can't lock; skip this source
		}
		defer release()

		// Re-check under lock.
		m2, _ := readMarker(c.markerPath(s))
		if isMarkerActiveForPrune(m2) {
			return nil
		}

		_ = os.Remove(c.dataPath(s))
		_ = os.Remove(c.markerPath(s))
		_ = os.Remove(c.tmpPath(s))
		return nil
	})
}

// ---- internal ---------------------------------------------------------------

type claimResult struct {
	claimed bool
	marker  *refreshMarker
}

// claimRefresh implements Algorithm 1 from ADR-012. Must be called with the
// source directory already created (ensured by refreshAndCommit).
func (c *Cache) claimRefresh(s Source) (claimResult, error) {
	release, err := c.acquireLock(s)
	if err != nil {
		return claimResult{}, err
	}
	defer release()

	existing, _ := readMarker(c.markerPath(s))
	if existing != nil {
		if isStale(s, existing) {
			_ = os.Remove(c.markerPath(s))
		} else {
			return claimResult{claimed: false, marker: existing}, nil
		}
	}

	m := &refreshMarker{
		PID:       os.Getpid(),
		StartedAt: time.Now().UTC(),
		Deadline:  time.Now().UTC().Add(s.RefreshDeadline),
	}
	if werr := writeMarker(c.markerPath(s), m); werr != nil {
		return claimResult{}, werr
	}
	return claimResult{claimed: true}, nil
}

// refreshAndCommit implements Algorithm 2 from ADR-012.
func (c *Cache) refreshAndCommit(s Source, fn Refresher) error {
	if err := os.MkdirAll(filepath.Join(c.Root, s.Tier), 0o750); err != nil {
		return err
	}

	claim, err := c.claimRefresh(s)
	if err != nil {
		return err
	}
	if !claim.claimed {
		// Another process is refreshing; wait for it.
		return c.waitForRefresh(s, claim.marker)
	}

	// We hold the claim. Run slow IO outside any lock.
	data, fetchErr := fn(context.Background())
	if fetchErr != nil {
		c.releaseMarker(s)
		return fetchErr
	}

	if werr := atomicWrite(c.dataPath(s), data); werr != nil {
		c.releaseMarker(s)
		return werr
	}

	c.releaseMarker(s)
	return nil
}

// waitForRefresh implements Algorithm 3 from ADR-012. Polls until the marker
// disappears or becomes stale, then returns (data has been written).
func (c *Cache) waitForRefresh(s Source, m *refreshMarker) error {
	// Poll until deadline + staleness_threshold or s.RefreshDeadline, whichever first.
	threshold := s.RefreshDeadline * stalenessMultiplier
	absoluteDeadline := m.Deadline.Add(threshold)
	maxWait := time.Now().Add(s.RefreshDeadline)
	if maxWait.Before(absoluteDeadline) {
		absoluteDeadline = maxWait
	}

	for time.Now().Before(absoluteDeadline) {
		time.Sleep(waitPollInterval)
		current, _ := readMarker(c.markerPath(s))
		if current == nil || isStale(s, current) {
			return nil
		}
	}
	return nil // timed out; caller will read whatever is on disk
}

// releaseMarker removes the .refreshing marker under the tier-1 lock, but
// only if our PID is still recorded (guard against PID-reuse races, per §2
// of refreshAndCommit pseudocode in ADR-012).
func (c *Cache) releaseMarker(s Source) {
	release, err := c.acquireLock(s)
	if err != nil {
		return
	}
	defer release()
	m, _ := readMarker(c.markerPath(s))
	if m != nil && m.PID == os.Getpid() {
		_ = os.Remove(c.markerPath(s))
	}
}

// ---- path helpers -----------------------------------------------------------

func (c *Cache) dataPath(s Source) string {
	return filepath.Join(c.Root, s.Tier, s.Name+".json")
}

func (c *Cache) lockPath(s Source) string {
	return filepath.Join(c.Root, s.Tier, s.Name+".lock")
}

func (c *Cache) markerPath(s Source) string {
	return filepath.Join(c.Root, s.Tier, s.Name+".refreshing")
}

func (c *Cache) tmpPath(s Source) string {
	return filepath.Join(c.Root, s.Tier, s.Name+".json.tmp")
}

package discoverycache

import (
	"context"
	"os"
	"path/filepath"
	"testing"
	"time"
)

func newTestCache(t *testing.T) *Cache {
	t.Helper()
	return &Cache{Root: t.TempDir()}
}

func testSource(name string, ttl, deadline time.Duration) Source {
	return Source{Tier: "discovery", Name: name, TTL: ttl, RefreshDeadline: deadline}
}

func TestReadEmpty(t *testing.T) {
	c := newTestCache(t)
	s := testSource("empty", time.Hour, 10*time.Second)
	res, err := c.Read(s)
	if err != nil {
		t.Fatal(err)
	}
	if res.Data != nil {
		t.Errorf("expected nil Data, got %d bytes", len(res.Data))
	}
	if !res.Stale {
		t.Error("expected Stale=true for empty cache")
	}
	if res.Fresh {
		t.Error("expected Fresh=false for empty cache")
	}
}

func TestReadAfterWrite(t *testing.T) {
	c := newTestCache(t)
	s := testSource("after-write", time.Hour, 10*time.Second)
	want := []byte(`{"hello":"world"}`)

	if err := c.Refresh(s, func(_ context.Context) ([]byte, error) { return want, nil }); err != nil {
		t.Fatal(err)
	}

	res, err := c.Read(s)
	if err != nil {
		t.Fatal(err)
	}
	if string(res.Data) != string(want) {
		t.Errorf("Read() = %q, want %q", res.Data, want)
	}
	if !res.Fresh {
		t.Errorf("expected Fresh=true, Age=%v TTL=%v", res.Age, s.TTL)
	}
	if res.Stale {
		t.Error("expected Stale=false after write")
	}
}

func TestReadStaleByMtime(t *testing.T) {
	c := newTestCache(t)
	s := testSource("stale-mtime", time.Hour, 10*time.Second)

	if err := c.Refresh(s, func(_ context.Context) ([]byte, error) { return []byte(`{}`), nil }); err != nil {
		t.Fatal(err)
	}
	// Backdate the file's mtime by 2h to make it stale.
	past := time.Now().Add(-2 * time.Hour)
	if err := os.Chtimes(c.dataPath(s), past, past); err != nil {
		t.Fatal(err)
	}

	res, err := c.Read(s)
	if err != nil {
		t.Fatal(err)
	}
	if res.Fresh {
		t.Errorf("expected Fresh=false, Age=%v TTL=%v", res.Age, s.TTL)
	}
	if !res.Stale {
		t.Error("expected Stale=true for backdated file")
	}
	if res.Data == nil {
		t.Error("expected stale Data to be non-nil")
	}
}

func TestRefreshIdempotent(t *testing.T) {
	c := newTestCache(t)
	s := testSource("idempotent", time.Hour, 10*time.Second)
	for i := range 3 {
		if err := c.Refresh(s, func(_ context.Context) ([]byte, error) { return []byte(`{}`), nil }); err != nil {
			t.Fatalf("iter %d: %v", i, err)
		}
	}
	res, err := c.Read(s)
	if err != nil {
		t.Fatal(err)
	}
	if !res.Fresh {
		t.Error("expected Fresh=true after repeated Refresh")
	}
}

func TestReadIsSubHundredMs(t *testing.T) {
	// AC: Cache.Read returns within 100ms p99 under no-contention baseline.
	c := newTestCache(t)
	s := testSource("perf", time.Hour, 10*time.Second)
	if err := c.Refresh(s, func(_ context.Context) ([]byte, error) { return []byte(`{}`), nil }); err != nil {
		t.Fatal(err)
	}

	var maxDuration time.Duration
	for range 200 {
		start := time.Now()
		if _, err := c.Read(s); err != nil {
			t.Fatal(err)
		}
		if d := time.Since(start); d > maxDuration {
			maxDuration = d
		}
	}
	if maxDuration > 100*time.Millisecond {
		t.Errorf("Read() max = %v, want < 100ms", maxDuration)
	}
}

func TestPruneRemovesInactive(t *testing.T) {
	c := newTestCache(t)
	active := testSource("active", time.Hour, 10*time.Second)
	inactive := testSource("old", time.Hour, 10*time.Second)

	for _, s := range []Source{active, inactive} {
		if err := c.Refresh(s, func(_ context.Context) ([]byte, error) { return []byte(`{}`), nil }); err != nil {
			t.Fatal(err)
		}
	}

	if err := c.Prune([]Source{active}); err != nil {
		t.Fatal(err)
	}

	res, _ := c.Read(active)
	if res.Data == nil {
		t.Error("active source was pruned")
	}
	res2, _ := c.Read(inactive)
	if res2.Data != nil {
		t.Error("inactive source was not pruned")
	}
}

func TestPruneSkipsActiveMarker(t *testing.T) {
	c := newTestCache(t)
	s := testSource("locked", time.Hour, 30*time.Second)
	dir := filepath.Join(c.Root, s.Tier)
	if err := os.MkdirAll(dir, 0o750); err != nil {
		t.Fatal(err)
	}
	if err := atomicWrite(c.dataPath(s), []byte(`{}`)); err != nil {
		t.Fatal(err)
	}
	m := &refreshMarker{
		PID:       os.Getpid(),
		StartedAt: time.Now().UTC(),
		Deadline:  time.Now().UTC().Add(30 * time.Second),
	}
	if err := writeMarker(c.markerPath(s), m); err != nil {
		t.Fatal(err)
	}

	if err := c.Prune(nil); err != nil {
		t.Fatal(err)
	}

	if _, err := os.Stat(c.dataPath(s)); os.IsNotExist(err) {
		t.Error("Prune removed data file of actively-refreshing source")
	}
}

