// HarnessInfo describes a registered harness. Mirrors the public
// HarnessInfo type defined in CONTRACT-003. Internal callers use this to
// implement the public ListHarnesses surface without re-declaring the shape.
type HarnessInfo struct {
	Name                 string
	Type                 string // "native" | "subprocess"
	Available            bool
	Path                 string
	Error                string
	IsLocal              bool
	IsSubscription       bool
	AutoRoutingEligible  bool
	ExactPinSupport      bool
	DefaultModel         string
	SupportedPermissions []string
	SupportedReasoning   []string
	CostClass            string
}

// ExecuteRequest is the internal request carried into Harness.Execute. It
// is intentionally narrower than the public ExecuteRequest in CONTRACT-003:
// the agent's routing layer is expected to resolve provider/model/reasoning
// /permissions/timeouts before invoking a harness, so the harness sees a
// concrete, ready-to-run request.
type ExecuteRequest struct {
	// Prompt is the resolved user prompt sent to the model.
	Prompt string

	// SystemPrompt is the resolved system prompt; empty means harness default.
	SystemPrompt string

	// Provider is the resolved provider identifier when applicable. May be
	// empty for harnesses that have no provider concept (e.g. claude CLI).
	Provider string

	// Model is the resolved model identifier; empty means harness default.
	Model string

	// WorkDir is the working directory for tool operations. Required when
	// the chosen harness uses tools.
	WorkDir string

	// Permissions is "safe" | "supervised" | "unrestricted". Empty defaults to "safe".
	Permissions string

	// Temperature is the model sampling temperature requested by the caller.
	// Harness adapters may ignore it when their CLI has no equivalent control.
	Temperature float32

	// Seed is the requested sampling seed. Zero means unset/provider chooses.
	// Harness adapters may ignore it when their CLI has no equivalent control.
	Seed int64

	// Reasoning is the normalized public reasoning scalar. Empty/off means no
	// adapter flag should be emitted.
	Reasoning string

	// Timeout is the wall-clock cap for the entire request. 0 disables.
	Timeout time.Duration

	// IdleTimeout is the streaming-quiet cap. 0 uses harness default.
	IdleTimeout time.Duration

	// SessionLogDir overrides the per-run session-log directory; harness
	// uses this to direct progress traces into a per-bundle evidence dir.
	SessionLogDir string

	// SessionID is a stable identifier for the run, used in progress log
	// filenames and event metadata. Empty means the harness generates one.
	SessionID string

	// Metadata is echoed back into Event.Metadata (e.g. bead_id, attempt_id).
	Metadata map[string]string
}

// Harness is the internal contract every harness implementation in
// internal/harnesses/<name> satisfies. It is the minimal surface the agent
// dispatcher needs to route a resolved request into a backend.
//
// A Harness is responsible for emitting events on the returned channel until
// execution completes; the channel MUST be closed after the final event so
// downstream consumers can detect end-of-stream. The final event is always
// of type EventTypeFinal.
type Harness interface {
	// Info returns identity + capability metadata for this harness.
	Info() HarnessInfo

	// HealthCheck triggers a fresh probe (binary present, auth ok, etc.)
	// and returns nil if the harness is ready to execute.
	HealthCheck(ctx context.Context) error

	// Execute runs one resolved request. Events stream on the returned
	// channel; a single final event closes the stream. The first error
	// return is reserved for setup failures (binary missing, etc.) — once
	// the channel is returned, all per-run failures are reported via a
	// final event with Status != "success".
	Execute(ctx context.Context, req ExecuteRequest) (<-chan Event, error)
}

package modelref

import (
	"fmt"
	"strings"
)

// ModelRef is the canonical model identity used as the cache key and routing
// surface: <provider>/<id>.
// Provider is a lowercase slug (letters, digits, hyphens, dots; no slashes).
// ID preserves the provider's original casing and may contain slashes
// (e.g. openrouter sub-paths like "qwen/qwen3.6-27b").
type ModelRef struct {
	Provider string
	ID       string
}

// Parse splits s on the first "/" into Provider and ID.
//
//	"openrouter/qwen/qwen3.6-27b"  → {Provider:"openrouter", ID:"qwen/qwen3.6-27b"}
//	"vidar-ds4/deepseek-v4-flash"  → {Provider:"vidar-ds4", ID:"deepseek-v4-flash"}
func Parse(s string) (ModelRef, error) {
	idx := strings.IndexByte(s, '/')
	if idx < 0 {
		return ModelRef{}, fmt.Errorf("modelref: no '/' in %q", s)
	}
	r := ModelRef{
		Provider: s[:idx],
		ID:       s[idx+1:],
	}
	if err := r.Validate(); err != nil {
		return ModelRef{}, err
	}
	return r, nil
}

// String returns "<provider>/<id>".
func (r ModelRef) String() string {
	return r.Provider + "/" + r.ID
}

// Validate checks that Provider and ID are non-empty and that Provider
// satisfies the slug rules (lowercase letters, digits, hyphens, dots; no slashes).
func (r ModelRef) Validate() error {
	if r.Provider == "" {
		return fmt.Errorf("modelref: provider is empty")
	}
	if r.ID == "" {
		return fmt.Errorf("modelref: id is empty")
	}
	for i, c := range r.Provider {
		if !isProviderRune(c) {
			return fmt.Errorf("modelref: provider %q has invalid character %q at position %d", r.Provider, c, i)
		}
	}
	return nil
}

func isProviderRune(c rune) bool {
	return (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '.'
}

package discoverycache

// Algorithm 6 from ADR-012: in-process singleflight composition.
//
// Within a process, singleflight.Group ensures at most one goroutine runs
// refreshAndCommit per source key. Across processes, the file-based marker
// (Algorithm 1) provides the same guarantee. The two layers compose: if
// goroutine A holds the singleflight key, goroutine B blocks on the same
// goroutine and gets the same result — no redundant file IO. If process B
// wins the singleflight but process A already holds the file marker, process B
// falls into waitForRefresh.

// Refresh forces a synchronous refresh regardless of TTL. If a refresh is
// already in flight (another goroutine or process), Refresh waits for it to
// complete. In-process callers share one goroutine via singleflight.
func (c *Cache) Refresh(s Source, fn Refresher) error {
	_, err, _ := c.sf.Do(s.key(), func() (interface{}, error) {
		return nil, c.refreshAndCommit(s, fn)
	})
	return err
}

// MaybeRefresh triggers a background refresh when the data is stale or absent,
// then returns immediately. The caller always gets data from Read; MaybeRefresh
// only schedules the replenishment. Multiple concurrent callers for the same
// source share one background goroutine via singleflight.
func (c *Cache) MaybeRefresh(s Source, fn Refresher) {
	res, err := c.Read(s)
	if err != nil || res.Fresh {
		return
	}
	go func() {
		_, _, _ = c.sf.Do(s.key(), func() (interface{}, error) {
			return nil, c.refreshAndCommit(s, fn)
		})
	}()
}

package harnesses

import (
	"encoding/json"
	"fmt"
	"log/slog"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/easel/fizeau/internal/modelcatalog"
	"github.com/easel/fizeau/internal/reasoning"
)

const EmbeddedDiscoverySource = "embedded-cassette"

type ModelDiscoveryLoader func(harnessName, source string) (ModelDiscoverySnapshot, error)

type discoveryCacheKey struct {
	harnessName string
	source      string
}

type discoveryCacheEntry struct {
	snapshot ModelDiscoverySnapshot
	err      error
}

// ModelDiscoveryCache memoizes in-process discovery snapshots by harness and
// source. The embedded source is populated from the registry's cassette-backed
// model lists; live PTY refresh is intentionally out of scope here.
type ModelDiscoveryCache struct {
	mu      sync.Mutex
	loader  ModelDiscoveryLoader
	entries map[discoveryCacheKey]discoveryCacheEntry
}

func NewModelDiscoveryCache(loader ModelDiscoveryLoader) *ModelDiscoveryCache {
	if loader == nil {
		loader = LoadEmbeddedModelDiscoverySnapshot
	}
	return &ModelDiscoveryCache{
		loader:  loader,
		entries: make(map[discoveryCacheKey]discoveryCacheEntry),
	}
}

func (c *ModelDiscoveryCache) Snapshot(harnessName, source string) (ModelDiscoverySnapshot, error) {
	if c == nil {
		c = NewModelDiscoveryCache(nil)
	}
	key := discoveryCacheKey{
		harnessName: strings.TrimSpace(harnessName),
		source:      strings.TrimSpace(source),
	}
	if key.source == "" {
		key.source = EmbeddedDiscoverySource
	}
	c.mu.Lock()
	if entry, ok := c.entries[key]; ok {
		c.mu.Unlock()
		return entry.snapshot, entry.err
	}
	loader := c.loader
	c.mu.Unlock()

	snapshot, err := loader(key.harnessName, key.source)

	c.mu.Lock()
	c.entries[key] = discoveryCacheEntry{snapshot: snapshot, err: err}
	c.mu.Unlock()
	return snapshot, err
}

var defaultDiscoveryCache = NewModelDiscoveryCache(nil)

func CachedModelDiscoverySnapshot(harnessName, source string) (ModelDiscoverySnapshot, error) {
	return defaultDiscoveryCache.Snapshot(harnessName, source)
}

func LoadEmbeddedModelDiscoverySnapshot(harnessName, source string) (ModelDiscoverySnapshot, error) {
	cfg, ok := NewRegistry().Get(harnessName)
	if !ok {
		return ModelDiscoverySnapshot{}, fmt.Errorf("unknown harness %q", harnessName)
	}
	if len(cfg.Models) == 0 {
		return ModelDiscoverySnapshot{}, fmt.Errorf("harness %q has no embedded model discovery snapshot", harnessName)
	}
	if source == "" {
		source = EmbeddedDiscoverySource
	}
	return ModelDiscoverySnapshot{
		CapturedAt:      time.Now().UTC(),
		Models:          append([]string(nil), cfg.Models...),
		ReasoningLevels: append([]string(nil), cfg.ReasoningLevels...),
		Source:          source,
		Detail:          "embedded registry snapshot refreshed by model-discovery cassette tests",
	}, nil
}

type RunnerModelResolution struct {
	HarnessName       string `json:"harness_name"`
	RequestedModel    string `json:"requested_model,omitempty"`
	ResolvedModel     string `json:"resolved_model"`
	PriorDefaultModel string `json:"prior_default_model,omitempty"`
	Source            string `json:"source"`
	Surface           string `json:"surface"`
	Warning           string `json:"warning,omitempty"`
	Reason            string `json:"reason,omitempty"`
	ExplicitPin       bool   `json:"explicit_pin,omitempty"`
}

type modelCandidate struct {
	model  string
	parsed modelcatalog.ParsedModel
	power  int
	order  int
}

func ResolveRunnerModel(harnessName string, surface modelcatalog.Surface, requestedModel, fallbackDefault string) RunnerModelResolution {
	return resolveRunnerModel(defaultDiscoveryCache, harnessName, surface, requestedModel, fallbackDefault)
}

func ResolveRunnerModelWithCache(cache *ModelDiscoveryCache, harnessName string, surface modelcatalog.Surface, requestedModel, fallbackDefault string) RunnerModelResolution {
	if cache == nil {
		cache = defaultDiscoveryCache
	}
	return resolveRunnerModel(cache, harnessName, surface, requestedModel, fallbackDefault)
}

func resolveRunnerModel(cache *ModelDiscoveryCache, harnessName string, surface modelcatalog.Surface, requestedModel, fallbackDefault string) RunnerModelResolution {
	resolution := RunnerModelResolution{
		HarnessName:       harnessName,
		RequestedModel:    requestedModel,
		PriorDefaultModel: fallbackDefault,
		Surface:           string(surface),
		Source:            EmbeddedDiscoverySource,
	}

	requestedModel = strings.TrimSpace(requestedModel)
	if requestedModel != "" {
		resolution.ResolvedModel = requestedModel
		resolution.ExplicitPin = true
		snapshot, err := cache.Snapshot(harnessName, EmbeddedDiscoverySource)
		if err != nil {
			resolution.Warning = fmt.Sprintf("model discovery unavailable for explicit pin validation: %v", err)
			resolution.Reason = "explicit_pin_discovery_unavailable"
			return resolution
		}
		resolution.Source = snapshot.Source
		if !stringInSliceFold(requestedModel, snapshot.Models) {
			resolution.Warning = fmt.Sprintf("explicit model pin %q was not present in %s snapshot", requestedModel, snapshot.Source)
			resolution.Reason = "explicit_pin_absent_from_snapshot"
		}
		return resolution
	}

	snapshot, err := cache.Snapshot(harnessName, EmbeddedDiscoverySource)
	if err != nil {
		resolution.ResolvedModel = fallbackDefault
		resolution.Warning = fmt.Sprintf("model discovery lookup failed; using fallback default %q: %v", fallbackDefault, err)
		resolution.Reason = "discovery_lookup_failed"
		return resolution
	}
	resolution.Source = snapshot.Source

	catalog, err := modelcatalog.Default()
	if err != nil {
		resolution.ResolvedModel = fallbackDefault
		resolution.Warning = fmt.Sprintf("model catalog load failed; using fallback default %q: %v", fallbackDefault, err)
		resolution.Reason = "catalog_load_failed"
		return resolution
	}

	candidates := autoRoutableSnapshotCandidates(catalog, snapshot, surface)
	if len(candidates) == 0 {
		resolution.ResolvedModel = fallbackDefault
		resolution.Warning = fmt.Sprintf("model discovery snapshot %s had no auto-routable catalog candidates; using fallback default %q", snapshot.Source, fallbackDefault)
		resolution.Reason = "no_auto_routable_discovery_candidate"
		return resolution
	}
	sort.SliceStable(candidates, func(i, j int) bool {
		if cmp := candidates[i].parsed.Compare(candidates[j].parsed); cmp != 0 {
			return cmp < 0
		}
		if candidates[i].power != candidates[j].power {
			return candidates[i].power > candidates[j].power
		}
		return candidates[i].order < candidates[j].order
	})

	resolution.ResolvedModel = candidates[0].model
	if resolution.ResolvedModel != fallbackDefault {
		resolution.Reason = "discovery_default_changed"
	}
	return resolution
}

func autoRoutableSnapshotCandidates(catalog *modelcatalog.Catalog, snapshot ModelDiscoverySnapshot, surface modelcatalog.Surface) []modelCandidate {
	seen := make(map[string]bool)
	candidates := make([]modelCandidate, 0, len(snapshot.Models))
	for i, modelID := range snapshot.Models {
		modelID = strings.TrimSpace(modelID)
		if modelID == "" {
			continue
		}
		eligibility, ok := catalog.ModelEligibility(modelID)
		if !ok || !eligibility.AutoRoutable {
			continue
		}
		resolved, err := catalog.Resolve(modelID, modelcatalog.ResolveOptions{Surface: surface})
		if err != nil || resolved.ConcreteModel == "" {
			continue
		}
		if seen[resolved.ConcreteModel] {
			continue
		}
		seen[resolved.ConcreteModel] = true
		candidates = append(candidates, modelCandidate{
			model:  resolved.ConcreteModel,
			parsed: modelcatalog.Parse(resolved.ConcreteModel),
			power:  eligibility.Power,
			order:  i,
		})
	}
	return candidates
}

func stringInSliceFold(needle string, haystack []string) bool {
	for _, candidate := range haystack {
		if strings.EqualFold(strings.TrimSpace(candidate), needle) {
			return true
		}
	}
	return false
}

